1	// === Types ===
2	type Customer = { yearsWithMHPCO: number };
3	type Item = { type: string; cursed?: boolean; enchantment?: number };
4	type Damage = { itemType: string; amount: number };
5	type Incident = { cause: string; damages: Damage[] };
6	type QuoteStep = { op: "quote"; items: Item[] };
7	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
8	type Step = QuoteStep | ClaimStep;
9	type Scenario = { customer: Customer; steps: Step[] };
10	type Policy = { items: Item[]; remainingCap: number };
11	
12	// === Premium constants ===
13	const PROCESSING_FEE = 5;
14	const FIRST_INSURANCE_RATE = 0.1;
15	const LOYALTY_DISCOUNT_RATE = 0.2;
16	const LOYALTY_YEARS_THRESHOLD = 2;
17	const FOLLOWUP_DISCOUNT_RATE = 0.15;
18	const CURSE_RATE = 0.5;
19	const HIGH_ENCHANTMENT_RATE = 0.3;
20	const HIGH_ENCHANTMENT_THRESHOLD = 5;
21	
22	const BASE_PREMIUMS: Record<string, number> = {
23	  sword: 100,
24	  amulet: 60,
25	  staff: 80,
26	  potion: 40,
27	  rune: 25,
28	  moonstone: 25,
29	};
30	
31	// === Component-block constants ===
32	const BLOCK_SIZE = 3;
33	const COMPONENT_BLOCK_PRICE = 60;
34	const COMPONENT_TYPES = ["rune", "moonstone"];
35	
36	// === Policy / claim constants ===
37	const DEDUCTIBLE = 100;
38	const CAP_MULTIPLIER = 2;
39	const INSURANCE_VALUE_MULTIPLIER = 10;
40	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
41	const HALF_REIMBURSEMENT_RATE = 0.5;
42	
43	// === Generic helpers ===
44	const sumBy = <T>(items: T[], selector: (item: T) => number): number =>
45	  items.reduce((sum, item) => sum + selector(item), 0);
46	
47	const rateIfApplies = (applies: boolean, base: number, rate: number): number =>
48	  applies ? base * rate : 0;
49	
50	// === Base premium ===
51	const basePremium = (item: Item): number => {
52	  const price = BASE_PREMIUMS[item.type];
53	  if (price === undefined) throw new Error(`unknown item type: ${item.type}`);
54	  return price;
55	};
56	
57	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
58	
59	const isHighlyEnchanted = (item: Item): boolean =>
60	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD;
61	
62	const itemSurcharge = (item: Item): number => {
63	  const base = basePremium(item);
64	  return rateIfApplies(item.cursed ?? false, base, CURSE_RATE)
65	       + rateIfApplies(isHighlyEnchanted(item), base, HIGH_ENCHANTMENT_RATE);
66	};
67	
68	const isComponentBlock = (sameTypeItems: Item[]): boolean =>
69	  sameTypeItems.length === BLOCK_SIZE && COMPONENT_TYPES.includes(sameTypeItems[0].type);
70	
71	const groupBasePremium = (sameTypeItems: Item[]): number =>
72	  isComponentBlock(sameTypeItems) ? COMPONENT_BLOCK_PRICE : sumBy(sameTypeItems, basePremium);
73	
74	const groupBy = <T>(items: T[], key: (item: T) => string): Map<string, T[]> => {
75	  const groups = new Map<string, T[]>();
76	  for (const item of items) {
77	    const k = key(item);
78	    const bucket = groups.get(k) ?? [];
79	    bucket.push(item);
80	    groups.set(k, bucket);
81	  }
82	  return groups;
83	};
84	
85	const totalBasePremium = (items: Item[]): number =>
86	  sumBy([...groupBy(items, (i) => i.type).values()], groupBasePremium);
87	
88	// === Policy-wide premium modifiers ===
89	const isLoyal = (customer: Customer): boolean =>
90	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
91	
92	const loyaltyDiscount = (base: number, customer: Customer): number =>
93	  rateIfApplies(isLoyal(customer), base, LOYALTY_DISCOUNT_RATE);
94	
95	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
96	
97	const followupDiscount = (base: number, isFollowup: boolean): number =>
98	  rateIfApplies(isFollowup, base, FOLLOWUP_DISCOUNT_RATE);
99	
100	const perItemSurcharges = (items: Item[]): number => sumBy(items, itemSurcharge);
101	
102	const premiumForItems = (items: Item[], customer: Customer, isFollowup: boolean): number => {
103	  const base = totalBasePremium(items);
104	  const surcharges = perItemSurcharges(items) + firstInsuranceSurcharge(base);
105	  const discounts = loyaltyDiscount(base, customer) + followupDiscount(base, isFollowup);
106	  return Math.ceil(base + surcharges - discounts + PROCESSING_FEE);
107	};
108	
109	// === Insurance / cap ===
110	const insuranceValue = (item: Item): number => basePremium(item) * INSURANCE_VALUE_MULTIPLIER;
111	
112	const insuranceSum = (items: Item[]): number => sumBy(items, insuranceValue);
113	
114	const policyCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
115	
116	// === Claim payout ===
117	const qualifiesForHalfReimbursement = (item: Item): boolean =>
118	  enchantmentLevel(item) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
119	
120	const reimbursementRate = (item: Item): number =>
121	  qualifiesForHalfReimbursement(item) ? HALF_REIMBURSEMENT_RATE : 1;
122	
123	const applyDeductible = (amount: number): number => Math.max(0, amount - DEDUCTIBLE);
124	
125	const findInsuredItem = (items: Item[], itemType: string): Item => {
126	  const item = items.find((i) => i.type === itemType);
127	  if (item === undefined) throw new Error(`uninsured item type: ${itemType}`);
128	  return item;
129	};
130	
131	const damagePayout = (damage: Damage, items: Item[]): number => {
132	  if (damage.amount < 0) throw new Error(`negative damage amount: ${damage.amount}`);
133	  const item = findInsuredItem(items, damage.itemType);
134	  return applyDeductible(damage.amount * reimbursementRate(item));
135	};
136	
137	// === Step handlers ===
138	const handleQuote = ({ items }: QuoteStep, customer: Customer, policies: Policy[]) => {
139	  const isFollowup = policies.length > 0;
140	  const premium = premiumForItems(items, customer, isFollowup);
141	  policies.push({ items, remainingCap: policyCap(items) });
142	  return { premium };
143	};
144	
145	const countBy = <T>(items: T[], key: (item: T) => string): Map<string, number> =>
146	  new Map([...groupBy(items, key)].map(([k, group]) => [k, group.length]));
147	
148	const assertDamageCounts = (damages: Damage[], items: Item[]): void => {
149	  const itemCounts = countBy(items, (i) => i.type);
150	  const damageCounts = countBy(damages, (d) => d.itemType);
151	  for (const [type, count] of damageCounts) {
152	    if (count > (itemCounts.get(type) ?? 0)) {
153	      throw new Error(`more damages of type ${type} than insured`);
154	    }
155	  }
156	};
157	
158	const claimPayout = (damages: Damage[], policy: Policy): number => {
159	  assertDamageCounts(damages, policy.items);
160	  const rawPayout = sumBy(damages, (d) => damagePayout(d, policy.items));
161	  return Math.min(Math.floor(rawPayout), policy.remainingCap);
162	};
163	
164	const handleClaim = ({ policy: policyIndex, incident }: ClaimStep, policies: Policy[]) => {
165	  const policy = policies[policyIndex];
166	  const payout = claimPayout(incident.damages, policy);
167	  policy.remainingCap -= payout;
168	  return { payout, remainingCap: policy.remainingCap };
169	};
170	
171	export const runScenario = ({ customer, steps }: Scenario): unknown => {
172	  const policies: Policy[] = [];
173	  const results = steps.map((step) =>
174	    step.op === "quote" ? handleQuote(step, customer, policies) : handleClaim(step, policies),
175	  );
176	  return { results };
177	};
